import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <mma.h>
#include <climits>
#include <cstdint>

using namespace cute;
using namespace nvcuda;

namespace cute_matmul_detail {

constexpr int TILE_M = 64;
constexpr int TILE_N = 64;
constexpr int TILE_K = 16;
constexpr int SMEM_B_STRIDE = TILE_N + 1;
constexpr int THREADS = 128;
constexpr int ITEMS_M = 8;
constexpr int ITEMS_N = 4;

__device__ __forceinline__ void cute_async_copy(float* dst, const float* src) {
#if __CUDA_ARCH__ >= 800
    uintptr_t dst_addr = reinterpret_cast<uintptr_t>(dst);
    uintptr_t src_addr = reinterpret_cast<uintptr_t>(src);
    if (((dst_addr | src_addr) & 0xF) == 0) {
        unsigned smem_addr = static_cast<unsigned>(__cvta_generic_to_shared(dst));
        asm volatile("cp.async.cg.shared.global [%0], [%1], 16;"
                     :: "r"(smem_addr), "l"(src));
    } else {
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            dst[i] = src[i];
        }
    }
#else
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        dst[i] = src[i];
    }
#endif
}
__device__ __forceinline__ void cute_commit_async() {
#if __CUDA_ARCH__ >= 800
    asm volatile("cp.async.commit_group;");
#endif
}
__device__ __forceinline__ void cute_wait_async() {
#if __CUDA_ARCH__ >= 800
    asm volatile("cp.async.wait_group 0;");
#endif
}
__global__ void cute_matmul_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ partial,
    int M,
    int N,
    int K,
    int splits)
{
    constexpr int STAGES = 2;
    constexpr int A_ELEMS = TILE_M * TILE_K;
    constexpr int B_ELEMS = TILE_K * TILE_N;
    constexpr int STAGE_ELEMS = A_ELEMS + TILE_K * SMEM_B_STRIDE;
    extern __shared__ float smem[];
    int tid = threadIdx.x;
    int split_id = blockIdx.z;
    int total_tiles = (K + TILE_K - 1) / TILE_K;
    int tile_begin = (total_tiles * split_id) / splits;
    int tile_end = (total_tiles * (split_id + 1)) / splits;
    int k_begin = tile_begin * TILE_K;
    int k_end = min(K, tile_end * TILE_K);
    auto gC = make_tensor(
        make_gmem_ptr(partial + static_cast<size_t>(split_id) * M * N),
        make_shape(M, N),
        make_stride(N, Int<1>{}));
    int warp_id = tid / 32;
    int block_row = blockIdx.y * TILE_M;
    int block_col = blockIdx.x * TILE_N;
    int warp_row = (warp_id / 2) * 32;
    int warp_col = (warp_id % 2) * 32;
    int row_base = (tid / 16) * ITEMS_M;
    int col_base = (tid % 16) * ITEMS_N;
    float accum[ITEMS_M][ITEMS_N];
    #pragma unroll
    for (int im = 0; im < ITEMS_M; ++im) {
        #pragma unroll
        for (int in = 0; in < ITEMS_N; ++in) {
            accum[im][in] = 0.0f;
        }
    }
    auto load_stage = [&](int stage, int k0) {
        float* stage_ptr = smem + stage * STAGE_ELEMS;
        float* stage_A = stage_ptr;
        float* stage_B = stage_ptr + A_ELEMS;
        constexpr int A_VECS = A_ELEMS / 4;
        for (int v = tid; v < A_VECS; v += THREADS) {
            int linear = v * 4;
            int local_m = linear / TILE_K;
            int local_k = linear % TILE_K;
            int gm = block_row + local_m;
            int gk = k0 + local_k;
            float* dst = stage_A + local_m * TILE_K + local_k;
            bool valid = gm < M && gk + 3 < k_end;
            if (valid) {
                cute_async_copy(dst, A + gm * K + gk);
            } else {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int kk = gk + x;
                    dst[x] = (gm < M && kk < k_end && kk < K)
                           ? A[gm * K + kk]
                           : 0.0f;
                }
            }
        }
        constexpr int B_VECS = B_ELEMS / 4;
        for (int v = tid; v < B_VECS; v += THREADS) {
            int linear = v * 4;
            int local_k = linear / TILE_N;
            int local_n = linear % TILE_N;
            int gk = k0 + local_k;
            int gn = block_col + local_n;
            float* dst = stage_B + local_k * SMEM_B_STRIDE + local_n;
            bool valid = gk < k_end && gn + 3 < N;
            if (valid) {
                cute_async_copy(dst, B + gk * N + gn);
            } else {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int nn = gn + x;
                    dst[x] = (gk < k_end && gk < K && nn < N)
                           ? B[gk * N + nn]
                           : 0.0f;
                }
            }
        }
        cute_commit_async();
    };
    if (k_begin < k_end) {
        load_stage(0, k_begin);
    }
    int stage = 0;
    for (int k0 = k_begin; k0 < k_end; k0 += TILE_K) {
        cute_wait_async();
        __syncthreads();
        int next_k = k0 + TILE_K;
        if (next_k < k_end) {
            load_stage(stage ^ 1, next_k);
        }
        float* stage_ptr = smem + stage * STAGE_ELEMS;
        float* tile_A = stage_ptr;
        float* tile_B = stage_ptr + A_ELEMS;
        #pragma unroll
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            #pragma unroll
            for (int im = 0; im < ITEMS_M; ++im) {
                float a = tile_A[(row_base + im) * TILE_K + kk];
                #pragma unroll
                for (int in = 0; in < ITEMS_N; ++in) {
                    float b = tile_B[kk * SMEM_B_STRIDE + col_base + in];
                    accum[im][in] = fmaf(a, b, accum[im][in]);
                }
            }
        }
        __syncthreads();
        stage ^= 1;
    }
    float* scratch = smem + STAGES * STAGE_ELEMS;
    #pragma unroll
    for (int im = 0; im < ITEMS_M; ++im) {
        #pragma unroll
        for (int in = 0; in < ITEMS_N; ++in) {
            int local_m = row_base + im;
            int local_n = col_base + in;
            scratch[local_m * SMEM_B_STRIDE + local_n] = accum[im][in];
        }
    }
    __syncthreads();
    constexpr int OUT_ELEMS = TILE_M * TILE_N;
    for (int linear = tid; linear < OUT_ELEMS; linear += THREADS) {
        int local_m = linear / TILE_N;
        int local_n = linear % TILE_N;
        int gm = block_row + local_m;
        int gn = block_col + local_n;
        if (gm < M && gn < N) {
            gC(gm, gn) = scratch[local_m * SMEM_B_STRIDE + local_n];
        }
    }
    }

__global__ void cute_matmul_reduce_kernel(
    float const* __restrict__ partial,
    float* __restrict__ C,
    int MN,
    int splits)
{
    int vec_count = (MN + 3) / 4;
    bool vectorized =
        (MN % 4 == 0) &&
        ((reinterpret_cast<uintptr_t>(partial) & 0xF) == 0) &&
        ((reinterpret_cast<uintptr_t>(C) & 0xF) == 0);
    for (int vec = blockIdx.x * blockDim.x + threadIdx.x;
         vec < vec_count;
         vec += blockDim.x * gridDim.x) {
        int base = vec * 4;
        if (vectorized) {
            float v0 = 0.0f;
            float v1 = 0.0f;
            float v2 = 0.0f;
            float v3 = 0.0f;
            for (int s = 0; s < splits; ++s) {
                auto const* src = reinterpret_cast<float4 const*>(partial +
                    static_cast<size_t>(s) * MN);
                float4 value = src[vec];
                v0 += value.x;
                v1 += value.y;
                v2 += value.z;
                v3 += value.w;
            }
            auto* dst = reinterpret_cast<float4*>(C);
            dst[vec] = make_float4(v0, v1, v2, v3);
        } else {
            for (int q = base; q < MN && q < base + 4; ++q) {
                float value = 0.0f;
                for (int s = 0; s < splits; ++s) {
                    value += partial[static_cast<size_t>(s) * MN + q];
                }
                C[q] = value;
            }
        }
    }
}

} // namespace cute_matmul_detail

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    TORCH_CHECK(A_contig.size(0) <= INT_MAX, "M is too large");
    TORCH_CHECK(A_contig.size(1) <= INT_MAX, "K is too large");
    TORCH_CHECK(B_contig.size(1) <= INT_MAX, "N is too large");
    int M = static_cast<int>(A_contig.size(0));
    int K = static_cast<int>(A_contig.size(1));
    int N = static_cast<int>(B_contig.size(1));

    auto C = torch::empty({M, N}, A_contig.options());

    if (M == 0 || N == 0) {
        return C;
    }
    if (K == 0) {
        return torch::zeros({M, N}, A_contig.options());
    }

    constexpr int TILE_K = cute_matmul_detail::TILE_K;
    int k_tiles = (K + TILE_K - 1) / TILE_K;
    int splits = std::min(32, k_tiles);
    auto partial = torch::empty(
        {splits, M, N},
        A_contig.options());

    dim3 block(cute_matmul_detail::THREADS);
    dim3 grid(
        (N + cute_matmul_detail::TILE_N - 1) / cute_matmul_detail::TILE_N,
        (M + cute_matmul_detail::TILE_M - 1) / cute_matmul_detail::TILE_M,
        splits);

    constexpr size_t shared_bytes =
        (2 * (cute_matmul_detail::TILE_M * cute_matmul_detail::TILE_K +
              cute_matmul_detail::TILE_K * cute_matmul_detail::SMEM_B_STRIDE) +
         cute_matmul_detail::TILE_M * cute_matmul_detail::SMEM_B_STRIDE) * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matmul_detail::cute_matmul_kernel<<<grid, block, shared_bytes, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        partial.data_ptr<float>(),
        M,
        N,
        K,
        splits);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE split-K matrix multiplication kernel launch failed");

    int mn = M * N;
    int reduce_blocks = (mn + 1023) / 1024;
    cute_matmul_detail::cute_matmul_reduce_kernel<<<reduce_blocks, 256, 0, stream>>>(
        partial.data_ptr<float>(),
        C.data_ptr<float>(),
        mn,
        splits);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE split-K reduction kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "--expt-extended-lambda",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

